\label{prop:classesAreChains}
   $\left\{\widehat{S^\mu_{k}}\right\}_{k=1}^\infty$ is a Markov chain over $\widehat{\mathcal{S}}$ with transition probabilities:
    $$p_\Delta(\widehat{s},\widehat{s}') = \begin{cases}
         1 + q(\widehat{s},\widehat{s})\Delta,& \widehat{s}' = \widehat{s}, \\
         q(\widehat{s},\widehat{s}')\Delta, & \text{otherwise.} 
    \end{cases}$$

\label{lemma:s-aHat}
    Let $\pi(s,a)$ be the basic feasible solution to the original problem \emph{OP} corresponding to $\mu$, so $\pi(s,\mu(s)) = \pi^\mu(s)$ and $\pi(s,a) = 0$ for $a\neq\mu(s)$. The $R$-aggregated state-action frequencies satisfy the following equality:
    $$\widehat{\pi}(\widehat{s,a}) =  \begin{cases}
         \widehat{\pi^\mu}(\widehat{s}), & \text{if there exists $(s',a')\in\widehat{s,a}$ such that $a'=\mu(s')$}, \\
         0, & \text{otherwise.} 
    \end{cases}$$

\label{claim:coherentFromNonCoherent}
Let $\mu$ be a non-coherent optimal policy for an impulsive CTMDP, implying that there exists at least one state $s$ such that $\mu(s)\neq 0$ and $\mu(s\oplus\mu(s))\neq0$. A coherent optimal policy can be constructed following this two-step process:
\begin{enumerate}
    \item Set $\mu'(s) = \begin{cases}
         \mu(s), & s \text{ is not looping,}  \\
         0, & s \text{ is looping.}
    \end{cases}.$ \\
    The policy $\mu'$ is optimal.
    \item Set $\mu''(s) = a_1 \oplus \dots \oplus a_{N(s)}$, where $\{a_n\}_{n=1}^\infty$ is the chain of $s$ under $\mu'$ and $N(s)$ is the degree of that chain. This policy $\mu''$ is optimal and coherent.
\end{enumerate}

\begin{align*}
        Q^\mu(s,a) &= (c(s,a)-g^\mu)t^+(s,a) + \mathbb{E}_{s'\sim q^+(s,a,\cdot)} h^\mu(s'), \text{ (by definition of $Q^\mu$)}\\
        &= (c(s\oplus a,0) - g^\mu)t^+(s\oplus a,0) + \mathbb{E}_{s'\sim q^+(s\oplus a,0,\cdot)} h^\mu(s'),\text{ (by impulsivity)}\\
        &= Q^\mu(s\oplus a,0),
    \end{align*}    
    where $t^+(s,a) = 1/q^-(s,a,s)$ is the sojourn time of state $s$ under action $a$ when allowing for ``dummy'' transitions back to $s$, and $h^\mu$ is the bias (i.e., relative value function) of policy $\mu$.

Let $\{\mathfrak{C}_i\}_{i=1}^I$ be a finite indexed set of impulsive CTMDPs  $\mathfrak{C}_i = \langle\mathcal{S}_i,\left(\mathcal{A}_i(s_i)\right)_{s_i\in\mathcal{S}_i},q^+_i:\mathcal{S}_i\times\mathcal{S}_i\to\mathbb{R}_{\geq0}, \oplus_i:\mathcal{SA}_i\to\mathcal{S}_i\rangle.$ We define the \emph{cost-free direct product} of these impulsive CTMDPs as the costless impulsive CTMDP:
    $$\bigotimes_{i=1}^I\mathfrak{C}_i := \langle\mathcal{S},\left(\mathcal{A}(s)\right)_{s\in\mathcal{S}}, q^+:\mathcal{S}\times\mathcal{S}\to\mathbb{R}_{\geq0}, \oplus:\mathcal{SA}\to\mathcal{S}\rangle,$$
    satisfying:
    \begin{align*}
        \mathcal{S} &= \bigtimes_{i=1}^I\mathcal{S}_i\\
        \mathcal{A}(\bm{s}) &= \bigtimes_{i=1}^I \mathcal{A}_i([\bm{s}]_i)\\
        q^+(\bm{s},\bm{s}') &= \begin{cases}
             q_i^+([\bm{s}]_i, s'_i), & \bm{s}' = ([\bm{s}]_1,\dots,s_i',\dots,[\bm{s}]_I) \text{ for some }i,  \\
             0, & \text{otherwise,} 
        \end{cases}.\\
        \bm{s} \oplus \bm{a} &= ([\bm{s}]_1\oplus_1 [\bm{a}]_1,\dots,[\bm{s}]_I\oplus_I[\bm{a}]_I).
    \end{align*}
    Additionally, we refer to $\mathfrak{C}_i$ as the \emph{$i$th compartment} of the product CTMDP.

Let $\mathfrak{C}$ be a stochastically decomposable impulsive CTMDP with $I$ compartments and $K$ objectives. Then $c_k:\mathcal{S}\to\mathbb{R}$ is:
     \begin{itemize}
         \item an \emph{additive cost function} if there exist functions $c_{i,k}:\mathcal{S}_i\to\mathbb{R}$ such that $c_k(\bm{s}) = \sum_{i=1}^I c_{i,k}([\bm{s}]_i).$
        \item a \emph{multiplicative cost function} if there exist functions $c_{i,k}:\mathcal{S}_i\to\mathbb{R}$ such that $c_k(\bm{s}) = \prod_{i=1}^I c_{i,k}([\bm{s}]_i).$
        \item  a \emph{logical-OR cost function} if there exist subsets $E_i\subset\mathcal{S}_i$ for each $i$ such that $c_k(\bm{s}) = \mathbb{I}\left\{\bigvee_{i=1}^I [\bm{s}]_i\in E_i\right\}.$
     \end{itemize}

\label{coro:stationaryIndep}


    The random variables $\widehat{S^\mu}$ and $\widehat{S^\mu_i}$ satisfy the following equalities:  
    \begin{align*}
        \mathbb{P}(\widehat{S^\mu} = \widehat{\bm{s}}) &= \prod_{i=1}^I \mathbb{P}(\widehat{S^{\mu}_i} = [\widehat{\bm{s}}]_i), \text{ for all }\widehat{\bm{s}}\in\widehat{\mathcal{S}},\\
        \mathbb{P}(\widehat{S^{\mu}_i} = \widehat{v}) &= \sum_{\widehat{\bm{s}}:[\widehat{\bm{s}}]_i = \widehat{v}}\mathbb{P}(\widehat{S^\mu} = \widehat{\bm{s}}), \text{ for all }i \text{ and }\widehat{v}\in\widehat{\mathcal{S}_i}.
    \end{align*}

By \autoref{coro:unifToCont}, we know the $\widehat{S^{\mu}_i}$ are the stationary distributions of the discrete-time Markov chains $\widehat{S^{\mu}_{i,k}}$, and that the $i$ chains are independent. Firstly, we see:
    \begin{align*}
        \mathbb{P}(\widehat{S^\mu} = \widehat{\bm{s}}) &= \mathbb{P}\left(\bigcap_{i=1}^I \left(\left[\widehat{S^\mu}\right]_i = [\widehat{\bm{s}}]_i\right)\right)\\

        &= \prod_{i=1}^I \mathbb{P}(\widehat{S^\mu_i} = [\widehat{\bm{s}}]_i),\text{ by independence of the }\widehat{S^\mu_i}.
    \end{align*}
    Secondly, we have: 
    \begin{align*}
        \mathbb{P}(\widehat{S^\mu_i} = \widehat{v}) &= \mathbb{P}([\widehat{S^\mu}]_i = \widehat{v})\\
        &= \mathbb{P}(\widehat{S^\mu}\in\{\widehat{\bm{s}}:[\widehat{\bm{s}}]_i = \widehat{v}\})\\
        &= \sum_{\widehat{\bm{s}}:[\widehat{\bm{s}}]_i = \widehat{v}}\mathbb{P}(\widehat{S^\mu} = \widehat{\bm{s}}).
    \end{align*}

\label{prop:notPFimpliesNotPF}
    Let $\mathfrak{C}$ be a decomposable impulsive CTMDP with compartments $\mathfrak{C}_i$. A solution to DC-MP is Pareto-optimal only if the compartment policies $\mu_i$ are Pareto-optimal with respect to the vector objective functions $\bm{g}_i$.
    If a policy $\mu = (\mu_1,\dots,\mu_I)$ has sub-policies $\mu_{i}$ that are not Pareto-optimal, then there exists a solution $\mu'$ with Pareto-optimal sub-policies such that the objective values of $\mu$ are bounded below by $\mu'$.

We see:
\begin{align*}
    Q^{\mu^*}_t(s,a_1\oplus a_2) &= Q^{\mu^*}_t(s\oplus a_1, a_2) &\text{ (by impulsivity)}\\
    &= (1+\varepsilon'(t))J^{\mu^*}_t(s\oplus a_1) &\text{ (by $\varepsilon'$-bound)}\\
    &\leq (1+\varepsilon'(t))Q^{\mu^*}_t(s\oplus a_1,0) &\text{ (by optimality of $J^{\mu^*}_t$)}\\
    &= (1+\varepsilon'(t))Q^{\mu^*}_t(s,a_1) &\text{ (by impulsivity)} \\
    &= (1+\varepsilon(t))(1+\varepsilon'(t))J^{\mu^*}_t(s) &\text{ (by $\varepsilon$-bound)}.
\end{align*}

We can also demonstrate that this bound is tight. Consider the following impulsive CTMDP:
\begin{align*}
    &\mathcal{S} = \{1,2,3\},\\
    &\mathcal{A}(1) = \{0,1,2\}, \mathcal{A}(2) = \{0,1\}, \mathcal{A}(3) = \{0\},\\
    & q^+(1,0,\cdot) = 0,\, q^+(2,0,s') = \left\{\begin{array}{cc}
         1, & s'=1, \\
         0, & \text{otherwise,}\\
    \end{array}\right. q^+(3,0,s') = \left\{ \begin{array}{cc}
        1, & s' = 1, \\
        0, & \text{otherwise,}
    \end{array} \right.\\
    & c(1) = 1, c(2)>c(1), c(3)>c(2),\\
    & s\oplus a = s+a.
\end{align*}

In words, state 1 is absorbing under the zero action and has the lowest cost rate, states 2 and 3 deterministically transition to state 1 after an expected sojourn time of 1, state 2 is more expensive than state 1, and state 3 is more expensive than state 2. Clearly, the average-optimal policy is $\mu^*(s) = 0$ for all $s$. In fact, this policy is optimal for all finite horizons, so we can write $V^*$ instead of $V^{\mu^*}$ and $Q^*$ instead of $Q^{\mu^*}$. We may evaluate the finite-horizon value functions:
\begin{align*}
    V^*(1;t) &= Q^*(1,0;t) = t\\
    V^*(2;t) &= Q^*(2,0;t)= \begin{cases}
         c(2)t, & t\in[0,1],  \\
         c(2) + (t-1), & t>1. 
    \end{cases}\\
    V^*(3;t) &= Q^*(3,0;t) = \begin{cases}
         c(3)t, & t\in[0,1],  \\
         c(3) + (t-1), & t>1. 
    \end{cases}
\end{align*}
In state 1, we always accumulate cost at rate 1. In state 2, we accumulate cost at rate $c(2)$ until time $t=1$ and then transition to state 1 and accumulate cost at rate 1. State 3 is the same except that $c(2)$ is replaced by $c(3)$. We may also evaluate the remaining action value functions and rewrite them in terms of error functions $\varepsilon(s,a;t)$ where $Q^*(s,a;t) = (1+\varepsilon(s,a;t))V^*(s;t)$, with $\varepsilon(\cdot,\cdot;0) = 0$:
\begin{align*}
    Q^*(1,1;t) &= V^*(2;t) \text{ (by impulsivity)}\\
               &= (1+\varepsilon(1,1;t))V^*(1;t), \text{ for } \varepsilon(1,1;t) = \left\{ \begin{array}{cc}
                    c(2)-1,& t\in(0,1], \\
                    \frac{c(2)-1}{t},& t>1,
               \end{array}\right.\\
    Q^*(1,2;t) &= V^*(3;t) \text{ (by impulsivity)}\\
               &= (1+\varepsilon(1,2;t))V^*(1;t), \text{ for } \varepsilon(1,2;t) = \left\{ \begin{array}{cc}
                    c(3)-1,& t\in(0,1], \\
                    \frac{c(3)-1}{t},& t>1,
               \end{array}\right.\\
    Q^*(2,1;t) &= V^*(3;t) \text{ (by impulsivity)}\\
               &= (1 + \varepsilon(2,1;t))V^*(2;t), \text{ for } \varepsilon(2,1;t) = \left\{ \begin{array}{cc}
                    \frac{c(3)}{c(2)} - 1,& t\in(0,1], \\
                    \frac{c(3)-c(2)}{c(2)-1+t},& t>1. 
               \end{array}\right.
\end{align*}
Some rearranging then shows that $(1+\varepsilon(1,2;t)) = (1+\varepsilon(1,1;t))(1+\varepsilon(2,1;t))$, where action $2$ in state $1$ is the sequenced action of action $1$ in state $1$ and action $1$ in state $2$.

The $\bm{\pi}_i$ correspond to basic feasible solutions of OP for each $\mathfrak{C}_i$, which in turn corresponds to coherent policies $\mu_i(v)=\arg\max_{b\in\mathcal{A}_i(v)}\pi_i(v,b)$. Together, these form the CS policy $\mu=(\mu_1,\dots,\mu_I)$ for the whole CTMDP $\mathfrak{C}$. Let $S^\mu$ be the stationary distribution of $\mathfrak{C}$ controlled by $\mu$. Now we define:
$$\pi(\bm{s},\bm{a}):=\begin{cases}
\mathbb{P}(S^\mu = \bm{s}),& \bm{a} = \mu(\bm{s}),\\ 
0,& \text{otherwise}.\end{cases}
$$
Then $\pi(\bm{s},\bm{a})$ provides a basic feasible solution to OP. Together with $y(\bm{s},\bm{a}):=\mathbb{I}\{\bm{a}=\mu(\bm{s})\}$, $(\bm{\pi},\bm{y})$ gives a solution to CS-MILP that satisfies the relevant equations.
